-- Real brand logos supplied by NBD, embedded directly as data URIs so
-- no storage upload step is needed. Davines and Living Proof aren't
-- included yet -- upload those from Admin > Brands & modules once a
-- clean logo file is available for each.

update brands set logo_url = 'data:image/png;base64,' where name = 'Eleven Australia';
update brands set logo_url = 'data:image/png;base64,' where name = 'Kevin.Murphy';
update brands set logo_url = 'data:image/png;base64,' where name = 'Color Wow';
update brands set logo_url = 'data:image/png;base64,' where name = 'Aveda';
update brands set logo_url = 'data:image/png;base64,' where name = 'K18';
